#!/usr/bin/env node
// Build-time export of selected UNSIGNED draft challenges
// (challenges/drafts/<name>.draft.json) into src/generated/drafts.ts, so the
// UI can show them as drafts. A draft is not registered on any server and is
// not open for submissions; this script never signs, hashes into a challenge
// id, or registers anything. Only the drafts named in EXPORT are exported
// (most files in challenges/drafts/ are historical or superseded).
//
//   node scripts/export-drafts.mjs           regenerate
//   node scripts/export-drafts.mjs --check   fail if the generated file is stale
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const EXPORT = ['near-chunk-v3'];

const web = join(dirname(fileURLToPath(import.meta.url)), '..');
const repo = join(web, '..');
const out = join(web, 'src/generated/drafts.ts');

const str = (v, what) => {
  if (typeof v !== 'string') throw new Error(`${what}: expected string`);
  return v;
};

function exportDraft(name) {
  const rel = `challenges/drafts/${name}.draft.json`;
  const bytes = readFileSync(join(repo, rel));
  const d = JSON.parse(bytes.toString('utf8'));
  if (d.name !== name) throw new Error(`${rel}: name is ${JSON.stringify(d.name)}, expected ${name}`);
  const s = d.semantic_scope;
  const classes = d.workload_suite.classes.map((c) => ({ id: str(c.id, 'class id'), description: str(c.description, 'class description') }));
  return {
    name,
    source_path: rel,
    source_sha256: createHash('sha256').update(bytes).digest('hex'),
    season: str(d.season, 'season'),
    tier: str(d.tier, 'tier'),
    created_at: str(d.created_at, 'created_at'),
    nearcore_tag: str(d.nearcore.tag, 'nearcore.tag'),
    nearcore_commit: str(d.nearcore.commit, 'nearcore.commit'),
    protocol_version: d.protocol_version,
    scope: {
      name: str(s.name, 'scope name'),
      kind: str(s.kind, 'scope kind'),
      granularity: str(s.granularity, 'scope granularity'),
      relation_module: str(s.formal_spec.relation_module, 'relation_module'),
      relation_decl: str(s.formal_spec.relation_decl, 'relation_decl'),
      restrictions: s.restrictions.map((r) => ({ id: str(r.id, 'restriction id'), text: str(r.text, 'restriction text') })),
      excludes: s.excludes.map((x) => str(x, 'exclude')),
    },
    coverage: d.coverage
      ? {
          statement_spec: str(d.coverage.statement_spec, 'statement_spec'),
          tiers: d.coverage.tiers.map((t) => ({ id: str(t.id, 'tier id'), rank: t.rank, classes: t.classes.map((c) => str(c, 'tier class')) })),
        }
      : null,
    classes,
    weight_status: str(d.workload_suite.weight_source?.status ?? 'unspecified', 'weight status'),
    security_profile: str(d.security_profile.id, 'security profile'),
    limits: {
      max_prove_ms: d.resource_limits.max_prove_ms,
      max_verify_ms: d.resource_limits.max_verify_ms,
      max_proof_bytes: d.resource_limits.max_proof_bytes,
      max_ram_bytes: d.resource_limits.max_ram_bytes,
    },
  };
}

const drafts = EXPORT.map(exportDraft);
const text =
  '// GENERATED by scripts/export-drafts.mjs from challenges/drafts/*.draft.json. Do not edit.\n' +
  '// These are UNSIGNED drafts: not registered, not open for submissions.\n' +
  "import type { DraftChallenge } from '../lib/drafts';\n\n" +
  `export const DRAFTS: DraftChallenge[] = ${JSON.stringify(drafts, null, 2)};\n`;

if (process.argv.includes('--check')) {
  const cur = existsSync(out) ? readFileSync(out, 'utf8') : '';
  if (cur !== text) {
    console.error('src/generated/drafts.ts is stale: run `node scripts/export-drafts.mjs`');
    process.exit(1);
  }
  console.log('export-drafts: up to date');
} else {
  writeFileSync(out, text);
  console.log(`export-drafts: wrote ${drafts.length} draft(s) to src/generated/drafts.ts`);
}
